def reverse_vowels(s):
    vowels = set('aeiouAEIOU')
    chars = list(s)
    left, right = 0, len(chars) - 1
    while left < right:
        if chars[left] not in vowels:
            left += 1
        elif chars[right] not in vowels:
            right -= 1
        else:
            chars[left], chars[right] = chars[right], chars[left]
            left += 1
            right -= 1
    return ''.join(chars)

def ordinal_suffix(n):
    a = abs(n)
    last_two = a % 100
    last_one = a % 10
    if last_two in (11, 12, 13):
        suffix = 'th'
    elif last_one == 1:
        suffix = 'st'
    elif last_one == 2:
        suffix = 'nd'
    elif last_one == 3:
        suffix = 'rd'
    else:
        suffix = 'th'
    return str(n) + suffix

def words_appearing_once(text):
    words = text.split()
    counts = {}
    for w in words:
        counts[w] = counts.get(w, 0) + 1
    return sorted([w for w in counts if counts[w] == 1])

def is_valid_markdown_link(s):
    import re
    match = re.match(r'^\[([^\]]*)\]\((.*)\)$', s)
    if not match:
        return False
    text, url = match.group(1), match.group(2)
    if not text:
        return False
    if not url or re.search(r'\s', url):
        return False
    return url.startswith('http://') or url.startswith('https://')

def split_on_sentinel(lst, sentinel):
