def dedupe_extension(name):
    idx = name.rfind(".")
    if idx == -1:
        return name
    ext = name[idx + 1:]
    idx2 = name.rfind(".", 0, idx)
    if idx2 == -1:
        return name
    prev_ext = name[idx2 + 1:idx]
    if ext and ext == prev_ext:
        return name[:idx]
    return name

def millis_to_clock(millis):
    ms = millis % 1000
    total_seconds = millis // 1000
    secs = total_seconds % 60
    mins = total_seconds // 60
    return "{:02d}:{:02d}.{:03d}".format(mins, secs, ms)

