def bucket_count_by_width(nums, width, start):
    if not nums:
        return []
    counts_map = {}
    for value in nums:
        idx = (value - start) // width
        counts_map[idx] = counts_map.get(idx, 0) + 1
    last_idx = (max(nums) - start) // width
    return [counts_map.get(i, 0) for i in range(last_idx + 1)]

